// ─── tests ───────────────────────────────────────────────────────────────

Test("Unique drops repeats", () =>
    Eq(Unique(new[] { "a", "b", "a" }), new List<string> { "a", "b" }));

Test("Unique keeps first-seen order", () =>
    Eq(Unique(new[] { "c", "a", "c", "b" }), new List<string> { "c", "a", "b" }));

Test("Unique of nothing is nothing", () => Eq(Unique(Array.Empty<string>()).Count, 0));

Test("Counts tallies each word", () =>
{
    var counts = Counts(new[] { "a", "b", "a" });
    Eq(counts["a"], 2);
    Eq(counts["b"], 1);
});

Test("Counts has one entry per distinct word", () =>
    Eq(Counts(new[] { "a", "a", "a" }).Count, 1));

Test("Counts of nothing is empty", () => Eq(Counts(Array.Empty<string>()).Count, 0));

Test("AnyDuplicates finds a repeat", () => Ok(AnyDuplicates(new[] { 1, 2, 1 })));

Test("AnyDuplicates is false for distinct ids", () => Ok(!AnyDuplicates(new[] { 1, 2, 3 })));

Test("AnyDuplicates is false for nothing", () => Ok(!AnyDuplicates(Array.Empty<int>())));

return Report();

// ─── tests ───────────────────────────────────────────────────────────────

Test("Lookup finds a present key", () =>
    Eq(Lookup(new Dictionary<string, string> { ["a"] = "1" }, "a"), "1"));

Test("Lookup returns empty for a missing key", () =>
    Eq(Lookup(new Dictionary<string, string>(), "nope"), ""));

Test("IndexByFirstLetter groups the words", () =>
{
    var index = IndexByFirstLetter(new[] { "ant", "bee", "ape" });
    Eq(index['a'], new List<string> { "ant", "ape" });
    Eq(index['b'], new List<string> { "bee" });
});

Test("IndexByFirstLetter has one key per distinct letter", () =>
    Eq(IndexByFirstLetter(new[] { "ant", "ape" }).Count, 1));

Test("IndexByFirstLetter keeps the input order inside a group", () =>
    Eq(IndexByFirstLetter(new[] { "ape", "ant" })['a'], new List<string> { "ape", "ant" }));

Test("IndexByFirstLetter of nothing is empty", () =>
    Eq(IndexByFirstLetter(Array.Empty<string>()).Count, 0));

Test("Invert swaps keys and values", () =>
{
    var inverted = Invert(new Dictionary<string, string> { ["a"] = "1", ["b"] = "2" });
    Eq(inverted["1"], "a");
    Eq(inverted["2"], "b");
});

Test("Invert keeps the last of a duplicated value", () =>
{
    var inverted = Invert(new Dictionary<string, string> { ["a"] = "1", ["b"] = "1" });
    Eq(inverted.Count, 1);
    Eq(inverted["1"], "b");
});

return Report();

// ─── tests ───────────────────────────────────────────────────────────────

var people = new[]
{
    new User("ada", true, 36),
    new User("linus", false, 54),
    new User("grace", true, 45),
};

Test("ActiveNames keeps only the active users", () =>
    Eq(ActiveNames(people), new List<string> { "ada", "grace" }));

Test("ActiveNames keeps the original order", () =>
    Eq(ActiveNames(people.Reverse()), new List<string> { "grace", "ada" }));

Test("ActiveNames of nobody is empty", () => Eq(ActiveNames(Array.Empty<User>()).Count, 0));

Test("Flatten concatenates the groups", () =>
    Eq(Flatten(new[] { new[] { "a" }, new[] { "b", "c" } }), new List<string> { "a", "b", "c" }));

Test("Flatten skips empty groups", () =>
    Eq(Flatten(new[] { Array.Empty<string>(), new[] { "a" } }), new List<string> { "a" }));

Test("Flatten of nothing is empty", () =>
    Eq(Flatten(Array.Empty<string[]>()).Count, 0));

Test("AverageAge averages", () => Approx(AverageAge(people), 45.0, 0.001));

Test("AverageAge of an empty list is zero, not an exception", () =>
    Approx(AverageAge(Array.Empty<User>()), 0.0));

return Report();

// ─── tests ───────────────────────────────────────────────────────────────

var sales = new[]
{
    new Sale("north", "widget", 100m),
    new Sale("south", "gadget", 150m),
    new Sale("north", "widget", 150m),
    new Sale("north", "gadget", 50m),
};

Test("TotalByRegion sums each region", () =>
{
    var totals = TotalByRegion(sales);
    Eq(totals["north"], 300m);
    Eq(totals["south"], 150m);
});

Test("TotalByRegion has one entry per region", () => Eq(TotalByRegion(sales).Count, 2));

Test("TotalByRegion of nothing is empty", () =>
    Eq(TotalByRegion(Array.Empty<Sale>()).Count, 0));

Test("BestSellerPerRegion picks the highest total per region", () =>
{
    var best = BestSellerPerRegion(sales);
    Eq(best["north"], "widget");
    Eq(best["south"], "gadget");
});

Test("BestSellerPerRegion sums a product before comparing", () =>
{
    var twoSmall = new[]
    {
        new Sale("east", "small", 60m),
        new Sale("east", "small", 60m),
        new Sale("east", "big", 100m),
    };
    Eq(BestSellerPerRegion(twoSmall)["east"], "small");
});

Test("RegionsWithAtLeast filters by group size", () =>
    Eq(RegionsWithAtLeast(sales, 2), new List<string> { "north" }));

Test("RegionsWithAtLeast returns them sorted", () =>
    Eq(RegionsWithAtLeast(sales, 1), new List<string> { "north", "south" }));

Test("RegionsWithAtLeast can return nothing", () =>
    Eq(RegionsWithAtLeast(sales, 99).Count, 0));

return Report();

// ─── tests ───────────────────────────────────────────────────────────────

var customers = new[]
{
    new Customer(1, "ada"),
    new Customer(2, "grace"),
    new Customer(3, "linus"),
};

var orders = new[]
{
    new Order(1, 100m),
    new Order(1, 50m),
    new Order(2, 25m),
};

Test("NamesWithOrders lists the buyers", () =>
    Eq(NamesWithOrders(customers, orders), new List<string> { "ada", "grace" }));

Test("NamesWithOrders names a repeat buyer once", () =>
    Eq(NamesWithOrders(customers, orders).Count(n => n == "ada"), 1));

Test("NamesWithOrders with no orders is empty", () =>
    Eq(NamesWithOrders(customers, Array.Empty<Order>()).Count, 0));

Test("TotalPerCustomer sums each customer's orders", () =>
{
    var totals = TotalPerCustomer(customers, orders);
    Eq(totals["ada"], 150m);
    Eq(totals["grace"], 25m);
});

Test("TotalPerCustomer keeps the customer who bought nothing", () =>
{
    var totals = TotalPerCustomer(customers, orders);
    Eq(totals.Count, 3, "a left join keeps every row on the left");
    Eq(totals["linus"], 0m);
});

Test("TotalPerCustomer with no orders still lists everyone", () =>
    Eq(TotalPerCustomer(customers, Array.Empty<Order>()).Count, 3));

Test("CustomersWithoutOrders finds the quiet ones", () =>
    Eq(CustomersWithoutOrders(customers, orders), new List<string> { "linus" }));

Test("CustomersWithoutOrders is empty when everyone bought something", () =>
    Eq(CustomersWithoutOrders(customers.Take(2), orders).Count, 0));

return Report();

